Method.Source:
    /// <summary>
    /// MPJ 22159 Collection note configure DCP 25/04/2022
    /// </summary>
    /// <param name="sender"></param>
    /// <param name="e"></param>
    [FormEventHandler(formStr(CustCollectionsNewActivityTask), FormEventType::PostRun)]
    public static void CustCollectionsNewActivityTask_OnPostRun(xFormRun sender, FormEventArgs e)
    {
        FormStringControl   typeIdControl;
        smmActivityTypeId   typeId;

        typeIdControl = sender.design().controlName(formControlStr(CustCollectionsNewActivityTask,smmActivities_TypeId));

        if(typeIdControl)
        {
            CustParameters  custParameters = CustParameters::find();

            typeId = custParameters.METActivityTypeId;

            if(typeId)
            {
                typeIdControl.text(typeId);
            }
        }
    }
